import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"訟","description":"焦氏易林注 - 訟","frontmatter":{"title":"訟","description":"焦氏易林注 - 訟"},"headers":[],"relativePath":"classics/jiaoyilin/006.md","filePath":"classics/jiaoyilin/006.md"}'),l={name:"classics/jiaoyilin/006.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="訟" tabindex="-1">訟 <a class="header-anchor" href="#訟" aria-label="Permalink to “訟”">​</a></h1><h3 id="訟-1" tabindex="-1">訟 <a class="header-anchor" href="#訟-1" aria-label="Permalink to “訟”">​</a></h3><h3 id="訟之乾" tabindex="-1">訟之乾 <a class="header-anchor" href="#訟之乾" aria-label="Permalink to “訟之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>文王四乳，仁愛篤厚。子蓄十男，夭折無有。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《遇》卦「訟」象。乾王離文，故曰文王。艮為乳，初二與三四皆形艮，故曰四乳，又巽數四也。乾為仁愛，伏坤為厚，震為子男，坤數十，故曰十男。坤為死，故曰夭。坎為折，震生故夭折無有。又全用《訟》伏。</p><h3 id="訟之坤" tabindex="-1">訟之坤 <a class="header-anchor" href="#訟之坤" aria-label="Permalink to “訟之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>日入望車，不見子家。長女無夫，左手搔頭。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此亦用《遇》卦「訟」象。離伏在下，故曰日入，《易》所謂後入於地也。離為望，伏震為車、為子，坎為室家。《訟》巽為長女，坎為夫，坎隱，故無。伏震為左，反艮為手、為搔，坎為頭，亦用《訟》伏。○車，依汲古，宋元本作東。</p><h3 id="訟之屯" tabindex="-1">訟之屯 <a class="header-anchor" href="#訟之屯" aria-label="Permalink to “訟之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>東上泰山，見堯自言。申理我冤，以解憂患。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮山震東，故曰泰山。震為帝、為言，故曰見堯自言。坎為冤、為憂患，震解。</p><h3 id="訟之蒙" tabindex="-1">訟之蒙 <a class="header-anchor" href="#訟之蒙" aria-label="Permalink to “訟之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>奎軫湯湯，過角宿房。宜時布和，無所不通。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為星。先天居西北對兌。兌居東南，故曰奎軫。奎，西北宿，軫，東南宿，而坤、坎皆為水，故曰湯湯。角、房，皆東方宿。震為東，故曰過角宿房。艮為時，坎為和、為通，震為軫，艮為角房尤切。○湯湯，依汲古，宋元本作溫湯。按：《天官書》：「奎為溝瀆，凡江河之事皆佔之」，又《星經》：「天江近尾。」軫南方宿，故曰湯湯。</p><h3 id="訟之需" tabindex="-1">訟之需 <a class="header-anchor" href="#訟之需" aria-label="Permalink to “訟之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>引髯牽頭，雖懼無憂。王母善禱，禍不成災。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>通《晉》。艮為引、為牽、為髯、為頭，坎為憂懼，坤安，故無憂。坤母乾王，故曰王母。坎上下皆兌口，故曰善禱。坎為禍災，坤安，故不災。○髯，依汲古，宋元本作船。頭，依宋元本，汲古作須。懼，依汲古，宋元作拘。</p><h3 id="訟之訟" tabindex="-1">訟之訟 <a class="header-anchor" href="#訟之訟" aria-label="Permalink to “訟之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>文巧俗弊，將反大質。僵死如麻，流血漂樐。皆知其母，不識其父，乾戈乃止。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。坤為文，坎為俗，巽為敝，震為反、為白，故曰大質。坤為死，震為麻，坎為血、為樐，坤水、坎水，故流血漂樐。《偽古文尚書武成篇》「血流漂杵」，《孟子》同杵，焦作樐。坤為母，乾為父，明滅故不知。離為乾戈。○樐，從宋元本，汲古及常本皆作杵。俗，汲古訛信，依宋元本。</p><h3 id="訟之師" tabindex="-1">訟之師 <a class="header-anchor" href="#訟之師" aria-label="Permalink to “訟之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>鳧得水沒，喜笑自啄。毛羽悅懌，利以攻玉。公出不復，伯氏客宿。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為鳧，坤水、坎水，故曰沒水。震為喜笑、為口、為啄，坤為自，故曰自啄。震為毛羽、為悅懌，為玉，伏巽為利，坎為破、為攻，故曰利以攻玉。震為公、為出、為復，坤死，故不復。震為伯、為客，坎為夜、為宿。○懌，從元本，宋本、汲古作澤，非。伯，依宋本，汲古訛柏，丁晏釋文不知其為訛字，以為柏氏即柏人，劉毓崧又以為柏谷，皆不知震為伯、為客故也。</p><h3 id="訟之比" tabindex="-1">訟之比 <a class="header-anchor" href="#訟之比" aria-label="Permalink to “訟之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>水流趨下，欲至東海。求我所有，買魴與鯉。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坎坤皆水，故曰趨下。坤為海，納乙，故曰東海。艮為求，坤為我、為魚，故曰魴鯉。○元本多「足關路止」四字，依汲古。</p><h3 id="訟之小畜" tabindex="-1">訟之小畜 <a class="header-anchor" href="#訟之小畜" aria-label="Permalink to “訟之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>獐鹿逐兔，安飽其居。反還次舍，無有疾故。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。艮為獐鹿，震為逐、為兔，在前故曰獐鹿逐兔。艮為居、為安，坎為飽，艮為次舍，震為反，故反次舍。坎為疾，震樂，故無疾。坤為死、為故。○有，汲古作乃，非，依宋元本。</p><h3 id="訟之履" tabindex="-1">訟之履 <a class="header-anchor" href="#訟之履" aria-label="Permalink to “訟之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>樹植藿豆，不得芸鋤。王事靡盬，秋無人收。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。震為藿豆，艮手為樹植、為芸鋤，坎陷，故不得。震為王，坤為事，震為行，故曰靡監。靡監，無定也，見《詩唐風》註。震為人，震伏故無。兌為秋。○人，依汲古，宋元本作所；又靡元本作無，非。</p><h3 id="訟之泰" tabindex="-1">訟之泰 <a class="header-anchor" href="#訟之泰" aria-label="Permalink to “訟之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>弱水之西，有西王母。生不知老，與天相保。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤水坤柔，故曰弱水。互兌為西，乾王坤母，故曰王母。震為生，乾為老，震樂，故不知老。乾為天，震為健，故曰與天相保。汲古多「行者危殆，利居善喜」二句，與上不協，依宋元本。元本註雲：「柳宗元曰西海之山有王母，神仙所居，其下有水，散渙無力，不能負芥。」</p><h3 id="訟之否" tabindex="-1">訟之否 <a class="header-anchor" href="#訟之否" aria-label="Permalink to “訟之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>數窮廓落，困於歷室。幸登玉堂，與堯佑食。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>乾為陽，九居數之極，故曰數窮。乾為遠，故廓落。艮為室、為時，故曰歷室。艮止為困，乾為玉，艮為堂，乾行，故登玉堂。乾為帝，故曰堯。伏兌為食。○幸，依汲古，宋元作卒。</p><h3 id="訟之同人" tabindex="-1">訟之同人 <a class="header-anchor" href="#訟之同人" aria-label="Permalink to “訟之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>子鋤執麟，春秋作經。元聖將終，尼父悲心。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為鋤、為子，坤文為麟，坎為獲，故曰子鋤執麟。震為春，坤為秋，坤為文，故曰春秋作經。乾為聖、為元，坤死，故曰終。乾為聖、為山，故曰尼父。坎為心、為悲。按：《左傳哀十四年》：「叔孫氏之車子鋤商獲麟」，《公羊》、《穀梁》皆以孔子感獲麟而作春秋，《後漢班固傳》註引《演孔圖》雲：「孔子母徵在夢，感黑龍而生孔子」，故曰元聖。《公羊》：「孔子見麟，反袂拭面，涕沽袍。」言孔子知將死而悲也。○經，依汲古，宋元本作「春秋作元，陰聖將終」，殊費解。又按：車子鋤商，杜註以車子連文，疏引《家語》服虔語以證其誤。今按：《易林》以子鋤連文，益足證杜註之非，惟王肅、服虔皆以子為姓，鋤商為名。今《易林》以子鋤連文，似以子鋤為姓，商乃其名，服氏、王氏仍誤也。又元字，據《演孔圖》疑為玄，今《漢書》為避清諱改，乃查元刊《易林》亦作元，是原作元，故從而不改。又按：此文下屢見，皆依汲古，此林校正音義皆協。</p><h3 id="訟之大有" tabindex="-1">訟之大有 <a class="header-anchor" href="#訟之大有" aria-label="Permalink to “訟之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>尹氏伯奇，父子生離。無罪被辜，長舌所為。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>周尹吉甫子伯奇為後母所讒，被逐，故曰父子生離。《林》用其事。此用《遇》卦「訟」象，《訟》通《明夷》，互震為尹、為伯、為子，《訟》天水違行，故曰父子生離。《訟》上乾為善，故曰無罪。坎為刑，故曰被辜。兌為舌，《明夷》互震似兌形而長，故曰長舌。</p><h3 id="訟之謙" tabindex="-1">訟之謙 <a class="header-anchor" href="#訟之謙" aria-label="Permalink to “訟之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>播木折枝，與母別離。九皋難和，絕不相知。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坎為播、為折，震為木、為枝，坤為母。播，種也，言折枝種於他處，故此枝與母木分離。震納庚、數九，艮為皋，故曰九皋，《詩》：「鶴鳴於九皋」。震為鶴，在山上高遠，故難和。○播木，宋元本作蟠枚，和作扣，均依汲古。後此詞屢見，皆依汲古此林校。</p><h3 id="訟之豫" tabindex="-1">訟之豫 <a class="header-anchor" href="#訟之豫" aria-label="Permalink to “訟之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>眵雞無距，與鵲格鬬。翅折目盲，為鳩所傷。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>旁通《小畜》。上巽為雞，半離，故眵目。《說文》：「眵目，傷眥也」。震為足，巽下斷，故無距。離為鵲、為鳩，兩兌口相對，故格鬥。震為羽，坎折，故翅折。震形目無上眥，故目盲。兌決，故為鳩所傷。○汲古多「復歸野廬，與母相扶」二句，與上義不屬，茲從宋元本。</p><h3 id="訟之隨" tabindex="-1">訟之隨 <a class="header-anchor" href="#訟之隨" aria-label="Permalink to “訟之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>甲乙丙丁，俱歸我庭。三醜六子，入門見母。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震東方，故曰甲乙。艮納丙，兌納丁，艮為庭，震為歸，故曰甲乙丙丁，俱歸我庭。巽貞醜，震數三，故曰三醜。卦六子俱備，故曰六子。艮為門，巽為入、為母，兌見，故曰入門見母。○以巽為母，可釋《蠱》母象。</p><h3 id="訟之蠱" tabindex="-1">訟之蠱 <a class="header-anchor" href="#訟之蠱" aria-label="Permalink to “訟之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>桑葉螟蠧，衣敝如絡。女工不成，絲布為玉。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽為桑、為螟蠧、為絡。震為衣，巽為敝，言桑壞蠶飢無所得絲，故衣敝如絡。巽為女、為工，巽下斷，故不成。巽為絲布，震為玉，言絲布貴如玉也。</p><h3 id="訟之臨" tabindex="-1">訟之臨 <a class="header-anchor" href="#訟之臨" aria-label="Permalink to “訟之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>開牢闢門，巡狩釋冤。夏臺羑里，湯文悅喜。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>伏艮為牢門，震為開、為巡狩、為釋，艮為臺、為裡，乾大，故曰夏臺。夏，大也。艮為道，故曰羑里。羑，道也。震為帝王，故曰湯文。震為樂，故悅喜。</p><h3 id="訟之觀" tabindex="-1">訟之觀 <a class="header-anchor" href="#訟之觀" aria-label="Permalink to “訟之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>欽明之德，坐前玉食。必保嘉美，長受安福。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為光明、為坐，伏震為玉，兌為食，震為佳美，坤為安。○美，汲古作善。</p><h3 id="訟之噬嗑" tabindex="-1">訟之噬嗑 <a class="header-anchor" href="#訟之噬嗑" aria-label="Permalink to “訟之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>武夫司空，多口爭訟。金火當戶，民不安處，年飢無有。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為武夫，艮為官，故曰司，離虛故曰司空。震為口，正反震，故曰多口、故曰爭訟。艮為戶、為金，離火，故曰金火當戶。金火，謂金星、火星也。《史記天官書》：「月五星順入軌道，其逆入若不軌道，以所犯命之，中坐成形，皆群下從謀也，金火尤甚」，故《後漢書天文志》：「孝和帝永元七年二月癸酉，金火俱在參，戊寅金火俱在東井」，特書其異。唐楊炯《渾天賦》：「金火犯之而甚憂」，茲曰當戶，是金火併見也。首二句似用《左傳》「宋華元使民築城，民謳歌嘲笑華元」故事。坎為民，坎險不安。震為年，離虛故飢。○按：此震為武人之證，《易》武人象舊說皆誤。</p><h3 id="訟之賁" tabindex="-1">訟之賁 <a class="header-anchor" href="#訟之賁" aria-label="Permalink to “訟之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>紫闕九重，尊嚴在中。黃帝堯舜，履行至公。冠帶垂裳，天下康寧。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮為闕，坎赤，故曰紫闕。震數九，上震覆，故曰九重。艮貴，故尊嚴。震為帝、為黃，故曰黃帝堯舜。震為履、為行，艮為冠，伏巽為帶。震為裳，艮為反震，故垂裳。震又為康寧也。○裳，從元本，宋本、汲古作衣。闕，宋元作閣。</p><h3 id="訟之剝" tabindex="-1">訟之剝 <a class="header-anchor" href="#訟之剝" aria-label="Permalink to “訟之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>負牛上山，力劣行難。烈風雨雪，遮遏我前，中道復還。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為背、為負、為山，坤牛，故曰負牛上山。震為行，震覆，故行難，坤柔，故力劣。坤為風、為冰霜，故曰烈風雨雪。艮止為遮遏。坤為我，艮為道，反震為還、為復。○依《旅》之「睽」校，宋元本多「憂苦日歡」四字，與上意不屬。</p><h3 id="訟之復" tabindex="-1">訟之復 <a class="header-anchor" href="#訟之復" aria-label="Permalink to “訟之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>蹇兔缺唇，行難齒寒。口病不言，為身生患。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為兔，伏巽下斷，故曰蹇、曰缺唇。震為行，坤閉，故難行。震為齒，坤為冰霜，故寒。震為口、為言，坤害，故曰病，坤閉故不言。坤為身、為患。震為生，故生患。○病，依元本，宋本、汲古作痛。</p><h3 id="訟之無妄" tabindex="-1">訟之無妄 <a class="header-anchor" href="#訟之無妄" aria-label="Permalink to “訟之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>合體比翼，嘉耦相得。與君同好，使我有福。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為體，正反艮相對，故曰合體。震為翼，正反震相連，故曰比翼、故曰嘉耦。乾君震君，故同好。乾為福，故曰有福。○嘉，從宋元本，汲古作喜，非。</p><h3 id="訟之大畜" tabindex="-1">訟之大畜 <a class="header-anchor" href="#訟之大畜" aria-label="Permalink to “訟之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>口啄卒卒，憂從中出。喪我寶貝，無妄失位。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>兌為口、為啄，震為卒卒。《漢書司馬遷傳》：「卒卒無須臾之間」，註：卒卒，促遽也。乾為惕、為憂，震為出、為寶，艮為貝，兌毀，故喪，無妄覆，故曰失位。○首句從宋本，汲古作「憒憒不脫」。無妄，汲古作亡妾，宋元本作妻妾，依下《升》林校。</p><h3 id="訟之頤" tabindex="-1">訟之頤 <a class="header-anchor" href="#訟之頤" aria-label="Permalink to “訟之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>兩心不同，或從西東。明論終日，莫適我從。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震起艮止，故兩心不同。震東，伏兌為西。艮明震論，艮終，伏乾為日，故明論終日。坤為我，震為從，下動上止，故莫適所從。○以艮為光明，凡《易》光明象得解。○我從，依汲古，宋元本作相從。</p><h3 id="訟之大過" tabindex="-1">訟之大過 <a class="header-anchor" href="#訟之大過" aria-label="Permalink to “訟之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>啞啞笑言，與喜飲食。長樂行觴，千秋起舞，拜受大福。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>兌為笑言、為飲食，伏震為喜、為樂、為觴、為起舞。兌為正秋，乾為千，故曰千秋。伏艮為拜，乾為大福。○喜，從汲古，宋元本作善。</p><h3 id="訟之坎" tabindex="-1">訟之坎 <a class="header-anchor" href="#訟之坎" aria-label="Permalink to “訟之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>初憂後喜，與福為市。八佾列陳，飲御嘉友。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎為憂，震為喜、為福，艮後天數八，震為佾，佾，樂舞。八佾，橫縱皆八。正反艮震，故用以為象，《易林》用象其精妙不可思議如此。伏巽為市，震為列陳、為飲御，艮為友。○嘉，依元本，宋本、汲古作諸。</p><h3 id="訟之離" tabindex="-1">訟之離 <a class="header-anchor" href="#訟之離" aria-label="Permalink to “訟之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>西徙無家，破其新車。王孫失利，不如止居。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>中爻兌為西，艮為家，艮伏，故無家。離為新，伏震為車，兌折，故破。伏震為王，艮為孫，巽為利，兌折，故失利。艮止艮居。○車，從宋元本，汲古作事，非。</p><h3 id="訟之鹹" tabindex="-1">訟之鹹 <a class="header-anchor" href="#訟之鹹" aria-label="Permalink to “訟之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>鳳凰在左，麒麟處右。仁聖相遇，伊呂積聚。時無殃咎，福為我母。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。坤為鳳凰、為麒麟，震左兌右，乾為仁聖，正反震兌口，故曰伊呂。伊，吾語聲。呂雙口，皆取象震兌。坤為積聚、為殃咎。艮為時，乾福坤母。</p><h3 id="訟之恆" tabindex="-1">訟之恆 <a class="header-anchor" href="#訟之恆" aria-label="Permalink to “訟之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>區脫康居，慕仁入朝。湛露之歡，三爵畢恩。復歸舊廬，與母相扶。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>對象。益中空，故曰區脫，兌西，故曰康居。震為仁、為朝，巽為入，故曰慕仁入朝。互大坎為湛露。湛露，《小雅》詩篇名，勞使臣也。震為歡、為爵，數三，故曰三爵。震為歸，艮為廬，坤為母，正反艮手，故曰相扶。故實詳蒙之鼎。○宋元本及汲古等本無末句，文勢不足，依蒙之鼎補，不惟文足與卦象尤覺神妙有味，且音協矣。</p><h3 id="訟之遯" tabindex="-1">訟之遯 <a class="header-anchor" href="#訟之遯" aria-label="Permalink to “訟之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>疾貧望幸，賈販市井。開牢擇羊，多得大牂。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>《獨斷》雲：「天子所臨曰幸，言或得賞賜而喜幸也」。伏坤為貧，艮為望。乾為福、為君，故曰幸。巽為賈販、為市井，艮為牢，伏震為開，兌為羊、為牂。牂，《說文》「牡羊也」。乾為大，故曰大牂。○汲古望幸下多「使伯行販」四字，宋元本無「賈販市井」四字，而元本下註雲：一雲疾貧望幸，賈販市井，幸、井為韻較幸販協矣，故從之。多得大牂，汲古訛「喜得天詳」。</p><h3 id="訟之大壯" tabindex="-1">訟之大壯 <a class="header-anchor" href="#訟之大壯" aria-label="Permalink to “訟之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>處高不傷，雖危不亡。握珠懷玉，還歸其鄉。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>伏巽為高，震樂故不傷、不危亡，伏坤為亡也。震為珠，乾為玉，伏艮，艮為握，震為歸，坤為鄉。</p><h3 id="訟之晉" tabindex="-1">訟之晉 <a class="header-anchor" href="#訟之晉" aria-label="Permalink to “訟之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>右手棄酒，左手收柈。行逢禮御，餌得玉杯。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為手，伏兌為右。坎為酒，離為左。柈，食器也。震為柈，二四震反，故曰收柈。坤為禮，艮為玉、為杯。○收柈，從汲古，宋元本作牧牂，似非。得，汲古作德，依宋元本。</p><h3 id="訟之明夷" tabindex="-1">訟之明夷 <a class="header-anchor" href="#訟之明夷" aria-label="Permalink to “訟之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>養虎牧狼，還自賊傷。大勇小捷，雖危不亡。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坤為虎狼、為牧養，坤喪，故賊傷，坎為賊也。震為勇捷，乾大坤小，坎險，故危。震樂坤安，故不亡。</p><h3 id="訟之家人" tabindex="-1">訟之家人 <a class="header-anchor" href="#訟之家人" aria-label="Permalink to “訟之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>戴堯扶禹，松喬彭祖。西遇王母，道路夷易，無敢難者。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>通《解》。震為帝，故曰堯禹。下兩半艮，艮為戴、為扶、為堅木、為壽，故為松喬彭祖。坎為西，震為王，巽為母，故曰王母。赤鬆子、王子喬，皆仙人。彭祖名籛，壽八百歲。《穆天子傳》：「穆王西巡，宴王母於瑤池之上」。艮為道路，坎為平，故曰夷易。夷者，平也。艮皆用半象。○巽母可解《易》。</p><h3 id="訟之睽" tabindex="-1">訟之睽 <a class="header-anchor" href="#訟之睽" aria-label="Permalink to “訟之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>秋冬探巢，不得鵲雛。銜指北去，愧我少姬。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>兌為秋，坎為冬、為巢，半艮為手，故曰探巢。離為鵲，兌為雛，坎失，故不得。兌口為銜，艮為指，坎北，故曰北去。坎為愧，兌為少姬。○愧，依宋本，汲古作慚，元本訛塊。</p><h3 id="訟之蹇" tabindex="-1">訟之蹇 <a class="header-anchor" href="#訟之蹇" aria-label="Permalink to “訟之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>兩羝三牂，俱之我鄉。留連多難，損其食糧。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>伏兌為羊，故曰羝、曰牂。羝、牂，皆牡羊也。兌卦數二，艮數三，故曰兩羝三牂。艮為鄉，坎陷艮止，故流連。坎為難，震為食、為糧，震覆故曰損。○牂，從宋元本，汲古作羊。我，宋元本作代，依汲古。</p><h3 id="訟之解" tabindex="-1">訟之解 <a class="header-anchor" href="#訟之解" aria-label="Permalink to “訟之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>南徙無廬，鳥破其巢。伐木思初，不利動搖。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為行、為南，艮為廬，艮覆，故曰南徙無廬。離為鳥，坎為巢，坎破，故鳥破其巢。震為木、為伐，坎為思，故曰伐木思初。《詩》：「伐木丁丁，鳥鳴嚶嚶」，言鳥尚知求友也。震為動搖，坎險，故不利。○鳥，從宋本，元本、汲古作烏，以《伐木》詩證之作鳥是。初，依宋元，汲古作切。</p><h3 id="訟之損" tabindex="-1">訟之損 <a class="header-anchor" href="#訟之損" aria-label="Permalink to “訟之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>爭訟不已，更相牽擊。張季弱口，被髮北走。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>二至上正反震，故爭訟，正反艮，故相擊。震為張，艮為季，坤柔兌口，故曰弱口。震為發，坤位北，故北走。○坤北之證。○擊，從汲古，與上協，宋元本作擊劍，非。顧千里本謂劍當作訽，與下走協，豈知擊與已協，走與口協，汲古可從。</p><h3 id="訟之益" tabindex="-1">訟之益 <a class="header-anchor" href="#訟之益" aria-label="Permalink to “訟之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>延頸望酒，不入我口。初喜後否，利得無有。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮為頸、為望，兌為酒，又為口，坤我。口象覆，故不入我口。震為喜、為後，坤喪，故初喜後否。巽為利，坤亡，故利得無有。○利得，依汲古，宋元本皆作得利。</p><h3 id="訟之夬" tabindex="-1">訟之夬 <a class="header-anchor" href="#訟之夬" aria-label="Permalink to “訟之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>被髮傾走，寇逐我後。亡失刀兵，身全不傷。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>通《剝》。震為發，震反，故被髮。被者，下垂也。震為走，震反故傾走。艮陽在上為刀兵，坤為亡失，故曰亡失刀兵。坤為身。○艮為刀證，兵傷韻。</p><h3 id="訟之姤" tabindex="-1">訟之姤 <a class="header-anchor" href="#訟之姤" aria-label="Permalink to “訟之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>麟鳳所遊，安樂無憂。君子撫民，世代千秋。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。坤為文、為麟鳳，震為遊、為樂，坤為憂，震樂，故安樂無憂。乾為君子，坤為民、為世、為千秋。</p><h3 id="訟之萃" tabindex="-1">訟之萃 <a class="header-anchor" href="#訟之萃" aria-label="Permalink to “訟之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>褰衣涉河，水深漬罷。賴幸舟子，濟脫無他。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤為衣裳，艮手為褰。坤為水，故曰涉河。上兌互大坎，下坤皆為水，故曰水深。坎勞故疲。伏震為舟、為子、為濟。○漬，依宋本，汲古作請，非。罷，同疲，《唐韻正》疲音皮，皮音婆。凡經傳罷倦之罷、罷休之罷，皆音婆。愚按：《詩召南》：「羔羊之皮，素絲五紽」，即協婆，此罷字與他協，與詩正同。又按：《左傳宣二年》：「牛則有皮，犀兕尚多」，協與此同。</p><h3 id="訟之升" tabindex="-1">訟之升 <a class="header-anchor" href="#訟之升" aria-label="Permalink to “訟之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>憒憒不悅，憂從中出。喪我金罌，無妄失位。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤迷，故曰憒憒。坤憂，故不悅。坤在外，故曰出。坤為喪、為我，伏艮為金，震為罌，故曰金罌。伏無妄故失位。○悅，從宋元本，汲古訛脫。喪，從宋本，元本作答，此與前《大畜》詞同，而大畜首句宋元本作「口啄卒卒」，於象較切，姑兩存之。</p><h3 id="訟之困" tabindex="-1">訟之困 <a class="header-anchor" href="#訟之困" aria-label="Permalink to “訟之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>絆跳不遠，心與言反。尼父望家，萏菡未華。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>巽為繩，伏震為跳，故曰絆跳，震反，故不遠。坎為心，三上正覆兌相背，故曰心與言反。《易》所謂有言不信者以此。伏震為父，艮為山，故曰尼父。互離為望，艮為家，故曰望家。兌為華、為萏菡，巽落故不華。○《易》有言不信得解。</p><h3 id="訟之井" tabindex="-1">訟之井 <a class="header-anchor" href="#訟之井" aria-label="Permalink to “訟之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>大牡肥牸，惠我諸舅。內外和穆，不憂饑渴。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。離為牛、為牡、為牸，震為父、為舅，正反震故曰諸舅。坎為和，內互大坎，外坎，故曰內外和穆。離為饑渴，坎為憂，震樂，故不憂。《詩伐木》篇「既有肥牡，以速諸舅」，林所本。○牡，各本皆作壯，惟元本舊註雲壯當作牡。按：《伐木》詩「既有肥牡」，元本註是也，故從之。牸，音字，牝牛也，其見於史漢者亦作牝馬，宋本訛為（牛孛）。</p><h3 id="訟之革" tabindex="-1">訟之革 <a class="header-anchor" href="#訟之革" aria-label="Permalink to “訟之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>黃帝建元，文德在身。祿若陽春，封為魯君。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為黃、為帝，為建。元者，首也，言黃帝始作甲子也。乾為首，坤為文、為身、為祿，震為陽春、為君，兌為魯，故曰魯君。</p><h3 id="訟之鼎" tabindex="-1">訟之鼎 <a class="header-anchor" href="#訟之鼎" aria-label="Permalink to “訟之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>虎聚磨牙，以待豚豬。往必傷亡，宜利止居。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。正反艮艮虎，故曰虎聚。艮為磨，兌為牙，正反兌，故磨牙。坎為豚豬，艮止，故曰待。震為行，坎災在上，故往必傷。艮為居止。○利，從宋元本，汲古作待，非。按：本卦巽亦為豬，乾亦為虎，但不如用旁通字字有著。</p><h3 id="訟之震" tabindex="-1">訟之震 <a class="header-anchor" href="#訟之震" aria-label="Permalink to “訟之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>天地配享，六位光明。陰陽順序，以成和平。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為口、為食，上下震，故曰天地配享。艮為位、為光明，坎數六，故曰六位光明。陽遇陰則通，故曰順序。坎為和平。○六，依蒙之小畜校，各本皆作立，非。○艮為光明可釋《易》。</p><h3 id="訟之艮" tabindex="-1">訟之艮 <a class="header-anchor" href="#訟之艮" aria-label="Permalink to “訟之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>猿墜高木，不踒手足。保我金玉，還歸其室。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為猿，在震上，故曰猿墜高木。艮為手，震為足，坎為折、為踒，震行，故不踒。艮為金、為保，震為玉，為反，艮為室。○墜，汲古作墮。○艮金可釋《易》。</p><h3 id="訟之漸" tabindex="-1">訟之漸 <a class="header-anchor" href="#訟之漸" aria-label="Permalink to “訟之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>營室紫宮，堅不可攻。明神建德，君受大福。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮為宮室、為星。營室，宿名，居亥方，艮象也。《天文志》：「紫宮為皇極之居」，即北辰也。坎赤，故曰紫。艮為堅、為明，伏震為神、為建、為君、為福。○建，從宋本，汲古訛達。</p><h3 id="訟之歸妹" tabindex="-1">訟之歸妹 <a class="header-anchor" href="#訟之歸妹" aria-label="Permalink to “訟之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>孤翁寡婦，獨宿悲苦。目張耳鳴，無與笑語。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為翁，坎為孤，伏巽為震婦，巽寡，故曰寡婦。坎為獨、為宿、為愁苦，互離為目，震為張、為鳴，坎耳，故曰目張耳鳴。震為笑語，坎孤，故無與笑語。</p><h3 id="訟之豐" tabindex="-1">訟之豐 <a class="header-anchor" href="#訟之豐" aria-label="Permalink to “訟之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>低頭竊視，有所畏避。行者不利，酒酸魚敗，眾莫貪嗜。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>艮為頭、為視，艮覆，故曰低頭、曰竊視。巽為伏，故曰畏避。震為行，巽顛趾，故不利。巽為魚、為臭，故曰魚敗。兌為酒，從木作酸，故酒酸。○利，依宋元本，汲古作至。竊，宋元本皆作窺，依汲古。</p><h3 id="訟之旅" tabindex="-1">訟之旅 <a class="header-anchor" href="#訟之旅" aria-label="Permalink to “訟之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>載金販狗，利棄我走。藏匿淵底，悔折為咎。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為車、為載、為商販。艮為金，又為狗，故曰載金販狗。震為走，巽為利，坎失，故曰利棄我走。坤為淵，坎為隱，坎入坤中，故曰藏匿淵底。兌為折。○以艮為金，《易》金象得解。</p><h3 id="訟之巽" tabindex="-1">訟之巽 <a class="header-anchor" href="#訟之巽" aria-label="Permalink to “訟之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>行觸大忌，與司命牾。執囚束系，拘制於吏。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏震為行、為觸，初至四大過死，故曰大忌。巽為命，初四正反兩巽相背，故與司命牾。《晉書天文志》：「文昌六星在北斗魁前，五曰司命。主壽。」《禮記》五祀之一。伏艮為拘繫、為官，故曰拘制於吏。○忌、牾，從宋元本，汲古作諱、作忤，亦通，然忌與下韻尤合。汲古下多「憂人有喜」四字，宋元本無此句，與上義不合，故從宋元本。又系字依汲古，與吏協，宋元本作縛，非。拘，依宋元，汲古作鉗。</p><h3 id="訟之兌" tabindex="-1">訟之兌 <a class="header-anchor" href="#訟之兌" aria-label="Permalink to “訟之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>執玉歡喜，佩之解攣。危詳反安，使我無患。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。艮為執，震為玉、為喜。中二句必有訛字，義未詳。○反，汲古作及，依宋元本。</p><h3 id="訟之渙" tabindex="-1">訟之渙 <a class="header-anchor" href="#訟之渙" aria-label="Permalink to “訟之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>機杼紛擾，女功不成。長女許嫁，衣無襦褲。聞禍不成，兇惡消去。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>坎為機杼。巽為繩、為女功，震為動，艮為成。二五正反震艮，故曰紛擾、曰不成。巽為長女，震為歸、為嫁、為言，故許嫁。震為襦，巽為褲，坎隱，故無襦褲。下二句疑贅。○紛，依宋元本，汲古作騰。功，依汲古，宋元作巧。女，依汲古，宋元作妹。○《震》襦可解《既濟》六四。</p><h3 id="訟之節" tabindex="-1">訟之節 <a class="header-anchor" href="#訟之節" aria-label="Permalink to “訟之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>金人鐵距，火燒左右。雖懼不恐，獨得全處。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為金鐵，震人震距，故曰金人鐵距。艮為火，震左兌右，故火燒左右。坎為憂恐，震樂艮安，故得全處。○距，依宋元，汲古訛巨。</p><h3 id="訟之中孚" tabindex="-1">訟之中孚 <a class="header-anchor" href="#訟之中孚" aria-label="Permalink to “訟之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>謝恩拜德，東歸吾國。舞蹈欣躍，歡樂受福。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>艮為拜，震為謝。兌為恩澤，震為東、為歸，艮為吾、為國。下二句皆震象。○吾，從宋元，汲古作吳，非。欣、歡，依宋元，汲古作歡、作恣。</p><h3 id="訟之小過" tabindex="-1">訟之小過 <a class="header-anchor" href="#訟之小過" aria-label="Permalink to “訟之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>青牛白咽，呼我俱田。厯山之下，可以多耕。歲樂時節，民人安寧。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為牛，震東方，色青，故曰青牛。巽色白，兌為咽，故曰白咽。咽，音燕，與田韻。震為呼、為耕，艮為山，兌為下，故曰山下。震為歲時、為樂，艮為安寧。○寧，從宋本，汲古作業。</p><h3 id="訟之既濟" tabindex="-1">訟之既濟 <a class="header-anchor" href="#訟之既濟" aria-label="Permalink to “訟之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>白雉群雊，慕德朝貢。湛露之恩，使我得歡。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>離為雉，震為白、為雊，重離，故群雊。坎為慕，震為朝，坎為露、為恩，震為歡。多用半象。○朝貢，依宋元，汲古作貢朝，非。歡，汲古訛懼，歡與恩韻。湛露，《詩》篇名。</p><h3 id="訟之未濟" tabindex="-1">訟之未濟 <a class="header-anchor" href="#訟之未濟" aria-label="Permalink to “訟之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>避患東西，反入禍門。糟糠不足，憂思我心。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>坎為避、為患、為西，離為東，故曰避患。東西艮為門，坎為禍，震為糟糠，離飢，故不足。坎為憂思、為心。艮震皆用半象。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
